def test_td_gt_split(mock_anndata):
    """Verifies splitting fractions, dictionary keys, and low-count skipping logic."""

    perturbations = ["pert_A", "pert_B", "pert_C"]
    
    td_set, gt_set = td_gt_split(mock_anndata, perturbations, td_ratio=0.5)
    
    # 1. Check that pert_C was skipped entirely due to having only 5 cells (< 10)
    assert "pert_C" not in td_set
    assert "pert_C" not in gt_set
    
    # 2. Check keys match unskipped perturbations
    assert set(td_set.keys()) == {"pert_A", "pert_B"}
    assert set(gt_set.keys()) == {"pert_A", "pert_B"}
    
    # 3. Check split sizes for pert_A (15 cells total -> 50% rounded up = 8 to TD, 7 to GT)
    assert len(td_set["pert_A"]) == 8
    assert len(gt_set["pert_A"]) == 7
    
    # 4. Check no data leakage (mutual exclusivity within the perturbation split)
    assert len(set(td_set["pert_A"]).intersection(set(gt_set["pert_A"]))) == 0


def test_technical_duplicate_math(mock_anndata):
    """Verifies that the generated dictionary profiles contain mathematically accurate averages."""
    
    # Manually configure an exact split for 'pert_A'
    td_set = {"pert_A": ["cell_0", "cell_1"]}
    gt_set = {"pert_A": ["cell_2"]}
    
    mu_td, mu_gt = technical_duplicate(mock_anndata, td_set, gt_set)
    
    # Compute ground truth arrays explicitly using numpy
    expected_td_mean = np.mean(mock_anndata[["cell_0", "cell_1"]].X, axis=0)
    expected_gt_mean = np.mean(mock_anndata[["cell_2"]].X, axis=0)
    
    # 1. Verify exact math values match array calculations
    np.testing.assert_array_almost_equal(mu_td["pert_A"], expected_td_mean)
    np.testing.assert_array_almost_equal(mu_gt["pert_A"], expected_gt_mean)
    
    # 2. Assert data type shapes equal the total gene count (5 genes)
    assert mu_td["pert_A"].shape == (5,)
    assert isinstance(mu_td["pert_A"], np.ndarray)


